import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Limit, Snapshot } from '../types'
import { barCells, countdown, tone } from './format'

const usage = atom({ plugin: 'usage-band', key: 'usage' } as const, null)
const now = atom({ plugin: 'usage-band', key: 'now' } as const, 0)

const TICK_MS = 30_000

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    try {
      const u = await $.session.usage()
      await update($, usage, () => ({ context: u.context, rateLimits: u.rateLimits }))
    } catch {
      // no reading yet; the first session.measure fills it in
    }
    const started = await $.clock.now()
    await update($, now, () => started)
    $.clock.every(TICK_MS, async () => {
      const t = await $.clock.now()
      await update($, now, () => t)
    })

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    const snapshot: Snapshot = { context: e.context, rateLimits: e.rateLimits }
    const t = await $.clock.now()
    await update($, usage, () => snapshot)
    await update($, now, () => t)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const snapshot = await read($, usage)
    if (e.props.hasSurvey || snapshot === null) return next(e)

    const t = (await read($, now)) || (await $.clock.now())
    const { Box, Text } = $.ui.resolve(e)
    const { context, rateLimits } = snapshot
    const five = rateLimits.find(l => l.kind === 'five_hour')
    const seven = rateLimits.find(l => l.kind === 'seven_day')

    // Flat Text pieces in one Box row: no fragments (the engine draws them as boxes).
    const dim = (text: string) => <Text dimColor>{text}</Text>
    const meter = (percent: number) => {
      const { filled, empty } = barCells(percent)
      return [
        <Text color={tone(percent)}>
          {'█'.repeat(filled)}
          {'░'.repeat(empty)} {Math.round(percent)}%
        </Text>,
      ]
    }
    const limit = (label: string, l: Limit | undefined) =>
      l
        ? [dim(`${label} `), ...meter(l.percentUsed), dim(` ${countdown(l.resetsAt, t)}`)]
        : [dim(`${label} —`)]

    return (
      <Box>
        {[
          dim('ctx '),
          ...(context.percent === undefined ? [dim('—')] : meter(context.percent)),
          dim('  │  '),
          ...limit('5h', five),
          dim('  │  '),
          ...limit('7d', seven),
        ]}
      </Box>
    )
  })
}

