/** Time left until `iso`, as "2h 14m", "3d 4h", "<1m", or "now" once past. */
export const countdown = (iso: string | undefined, now: number): string => {
  if (!iso) return '—'
  const ms = Date.parse(iso) - now
  if (Number.isNaN(ms)) return '—'
  if (ms <= 0) return 'now'
  const mins = Math.floor(ms / 60_000)
  if (mins < 1) return '<1m'
  const days = Math.floor(mins / 1440)
  const hours = Math.floor((mins % 1440) / 60)
  if (days > 0) return `${days}d ${hours}h`
  if (hours > 0) return `${hours}h ${mins % 60}m`
  return `${mins}m`
}

export const tone = (percent: number): 'success' | 'warning' | 'error' =>
  percent >= 85 ? 'error' : percent >= 60 ? 'warning' : 'success'

/** Cells of a half-height bar: how many are filled and how many are empty. */
export const barCells = (percent: number, width = 6): { filled: number; empty: number } => {
  const filled = Math.max(0, Math.min(width, Math.round((percent / 100) * width)))
  return { filled, empty: width - filled }
}

